import{readFile,writeFile}from'node:fs/promises';import{createHash}from'node:crypto';import{dirname,join}from'node:path';import{fileURLToPath}from'node:url';const d=dirname(fileURLToPath(import.meta.url)),a=await readFile(join(d,'src','base.bundle.plugin-v1.js'),'utf8'),b=await readFile(join(d,'src','kenig-events-standard-api.v1.js'),'utf8'),o=a.replace(/\s*$/u,'')+'\n'+b.replace(/^\s*/u,''),p=join(d,'dist','penpot-plugin.bundle.js');if(process.argv.includes('--check')){if(await readFile(p,'utf8')!==o)throw Error('DETERMINISTIC_REGENERATION_MISMATCH')}else await writeFile(p,o,'utf8');console.log(JSON.stringify({bytes:Buffer.byteLength(o),sha256:createHash('sha256').update(o).digest('hex')}));